https://connecticutinsuranceappraiser.com/ct-appraisal-services/homeowners-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Commercial, Condo & HOA Appraisal","url":"https://connecticutinsuranceappraiser.com/ct-appraisal-services/commercial-condo-hoa-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Roof & Hail Damage Appraisal","url":"https://connecticutinsuranceappraiser.com/ct-appraisal-services/roof-and-hail-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Wind & Tornado Damage Appraisal","url":"https://connecticutinsuranceappraiser.com/ct-appraisal-services/wind-and-tornado-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Hurricane & Tropical Storm Appraisal","url":"https://connecticutinsuranceappraiser.com/ct-appraisal-services/hurricane-and-tropical-storm-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Water & Frozen Pipe Damage Appraisal","url":"https://connecticutinsuranceappraiser.com/ct-appraisal-services/water-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Fire & Smoke Damage Appraisal","url":"https://connecticutinsuranceappraiser.com/ct-appraisal-services/fire-and-smoke-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Fallen Tree Damage Appraisal","url":"https://connecticutinsuranceappraiser.com/ct-appraisal-services/fallen-tree-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Ice Dam & Winter Storm Appraisal","url":"https://connecticutinsuranceappraiser.com/ct-appraisal-services/ice-dam-and-winter-storm-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Insurance Estimate Review","url":"https://connecticutinsuranceappraiser.com/ct-appraisal-services/insurance-estimate-review/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Umpire Services","url":"https://connecticutinsuranceappraiser.com/ct-appraisal-services/umpire-services/"}}]},"knowsAbout":["Insurance appraisal","Appraisal clause","Property claim valuation","Xactimate estimating","Fallen tree claims","Hurricane deductibles","Ice dam claims"],"openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}]},{"@type":"WebSite","@id":"https://connecticutinsuranceappraiser.com/#website","url":"https://connecticutinsuranceappraiser.com/","name":"Connecticut Insurance Appraiser","publisher":{"@id":"https://connecticutinsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://connecticutinsuranceappraiser.com/ct-claim-glossary/#webpage","url":"https://connecticutinsuranceappraiser.com/ct-claim-glossary/","name":"Insurance Claim Glossary | ACV, RCV, Umpire & More","description":"Searchable insurance claim glossary for Connecticut owners: ACV, RCV, depreciation, umpire, hurricane deductible, ice dam and more defined.","inLanguage":"en-US","isPartOf":{"@id":"https://connecticutinsuranceappraiser.com/#website"},"about":{"@id":"https://connecticutinsuranceappraiser.com/#business"},"publisher":{"@id":"https://connecticutinsuranceappraiser.com/#business"},"dateModified":"2026-11-17","primaryImageOfPage":{"@type":"ImageObject","url":"https://connecticutinsuranceappraiser.com/assets/img/photos/calculator-hands.webp","width":960,"height":640},"breadcrumb":{"@id":"https://connecticutinsuranceappraiser.com/ct-claim-glossary/#breadcrumb"},"mainEntity":{"@id":"https://connecticutinsuranceappraiser.com/ct-claim-glossary/#definedtermset"}},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://connecticutinsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Claim glossary","item":"https://connecticutinsuranceappraiser.com/ct-claim-glossary/"}],"@id":"https://connecticutinsuranceappraiser.com/ct-claim-glossary/#breadcrumb"},{"@type":"DefinedTermSet","name":"Connecticut property insurance claim glossary","hasDefinedTerm":[{"@type":"DefinedTerm","name":"Actual cash value (ACV)","description":"Replacement cost minus depreciation. Many policies pay ACV first and the rest after repairs.","inDefinedTermSet":"https://connecticutinsuranceappraiser.com/ct-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Additional living expense (ALE)","description":"Coverage for extra costs of living elsewhere while your home is being repaired, also called loss of use.","inDefinedTermSet":"https://connecticutinsuranceappraiser.com/ct-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Amount of loss","description":"The dollar value of a covered loss. This is the only question an appraisal panel decides.","inDefinedTermSet":"https://connecticutinsuranceappraiser.com/ct-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Appraisal award","description":"The written decision that sets the amount of loss. It is binding once signed by any two of the three panel members.","inDefinedTermSet":"https://connecticutinsuranceappraiser.com/ct-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Appraisal clause","description":"The policy condition that lets either party demand appraisal when they disagree about the amount of loss.","inDefinedTermSet":"https://connecticutinsuranceappraiser.com/ct-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Appraiser","description":"The person each side names to the panel. Policies usually require a competent and disinterested appraiser.","inDefinedTermSet":"https://connecticutinsuranceappraiser.com/ct-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Bad faith","description":"A general term for an insurer’s unreasonable handling of a claim. In Connecticut, related claims may involve CUIPA, CUTPA or common law. A legal question for an attorney.","inDefinedTermSet":"https://connecticutinsuranceappraiser.com/ct-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Coinsurance","description":"A commercial policy clause that can reduce payment if a property was insured for less than a required percentage of its value.","inDefinedTermSet":"https://connecticutinsuranceappraiser.com/ct-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Connecticut FAIR Plan","description":"Connecticut’s insurer of last resort for property owners who can’t obtain coverage in the voluntary market.","inDefinedTermSet":"https://connecticutinsuranceappraiser.com/ct-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Connecticut Insurance Department","description":"The state agency that regulates insurers, licenses adjusters and handles consumer complaints.","inDefinedTermSet":"https://connecticutinsuranceappraiser.com/ct-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Coverage A","description":"Dwelling coverage on a homeowners policy, used to calculate percentage deductibles.","inDefinedTermSet":"https://connecticutinsuranceappraiser.com/ct-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Coverage B","description":"Other structures coverage for detached garages, sheds, fences and similar structures.","inDefinedTermSet":"https://connecticutinsuranceappraiser.com/ct-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Coverage C","description":"Personal property, or contents, coverage.","inDefinedTermSet":"https://connecticutinsuranceappraiser.com/ct-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"CUIPA","description":"The Connecticut Unfair Insurance Practices Act, which lists unfair claim settlement practices.","inDefinedTermSet":"https://connecticutinsuranceappraiser.com/ct-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Debris removal","description":"Coverage for removing debris of covered property after a loss. Tree debris often has its own small limit.","inDefinedTermSet":"https://connecticutinsuranceappraiser.com/ct-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Declarations page","description":"The summary page of your policy listing coverages, limits and deductibles.","inDefinedTermSet":"https://connecticutinsuranceappraiser.com/ct-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Depreciation","description":"The reduction in value for age and wear, subtracted from replacement cost to get actual cash value.","inDefinedTermSet":"https://connecticutinsuranceappraiser.com/ct-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Disinterested","description":"Having no financial stake in the outcome. Appraisal clauses usually require disinterested appraisers.","inDefinedTermSet":"https://connecticutinsuranceappraiser.com/ct-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Hurricane deductible","description":"A deductible, often a percentage of Coverage A, that applies to losses from a hurricane when the policy’s trigger is met.","inDefinedTermSet":"https://connecticutinsuranceappraiser.com/ct-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Ice dam","description":"A ridge of ice at the eaves that traps meltwater, which can back up under shingles and leak inside.","inDefinedTermSet":"https://connecticutinsuranceappraiser.com/ct-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Line item","description":"A single entry on an estimate, such as a quantity of shingles or a square footage of drywall, with its unit price.","inDefinedTermSet":"https://connecticutinsuranceappraiser.com/ct-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Matching","description":"The issue of whether replacement materials reasonably match existing materials, which can affect how far repairs extend.","inDefinedTermSet":"https://connecticutinsuranceappraiser.com/ct-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Mitigation","description":"Reasonable steps to prevent further damage after a loss, such as tarping or drying. Usually a policy duty.","inDefinedTermSet":"https://connecticutinsuranceappraiser.com/ct-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Named storm","description":"A tropical system named by the National Hurricane Center. Some deductibles are triggered by named storms.","inDefinedTermSet":"https://connecticutinsuranceappraiser.com/ct-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Ordinance or law","description":"Coverage for added costs to meet current building codes during repairs, subject to its own limit.","inDefinedTermSet":"https://connecticutinsuranceappraiser.com/ct-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Overhead and profit (O&P)","description":"A general contractor’s charge for coordinating multiple trades, commonly 10% plus 10%.","inDefinedTermSet":"https://connecticutinsuranceappraiser.com/ct-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Pitch","description":"A roof’s slope expressed as rise over 12 inches of run, such as 9/12.","inDefinedTermSet":"https://connecticutinsuranceappraiser.com/ct-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Proof of loss","description":"A sworn statement of the amount claimed, which the insurer may request within a set time.","inDefinedTermSet":"https://connecticutinsuranceappraiser.com/ct-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Public adjuster","description":"A licensed professional who represents the policyholder in presenting and negotiating the whole claim for a fee.","inDefinedTermSet":"https://connecticutinsuranceappraiser.com/ct-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Recoverable depreciation","description":"Depreciation held back from the first payment and paid once repairs are completed under a replacement cost policy.","inDefinedTermSet":"https://connecticutinsuranceappraiser.com/ct-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Replacement cost value (RCV)","description":"The cost to repair or replace damaged property with materials of like kind and quality, without deducting depreciation.","inDefinedTermSet":"https://connecticutinsuranceappraiser.com/ct-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Scope","description":"The list of repairs needed to restore the property. Many disputes are about scope rather than price.","inDefinedTermSet":"https://connecticutinsuranceappraiser.com/ct-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Square","description":"100 square feet of roof surface.","inDefinedTermSet":"https://connecticutinsuranceappraiser.com/ct-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Standard fire policy","description":"A policy form set out in Connecticut statute, on which many property policies, including their appraisal provisions, are based.","inDefinedTermSet":"https://connecticutinsuranceappraiser.com/ct-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Steep charge","description":"An added labor charge for working on steep roofs, commonly applied from about 7/12 pitch.","inDefinedTermSet":"https://connecticutinsuranceappraiser.com/ct-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Storm surge","description":"Seawater pushed ashore by a storm. Usually excluded from homeowners policies and covered by flood insurance.","inDefinedTermSet":"https://connecticutinsuranceappraiser.com/ct-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Suit limitation","description":"The policy’s deadline for filing a lawsuit against the insurer.","inDefinedTermSet":"https://connecticutinsuranceappraiser.com/ct-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Supplement","description":"A request to add items or costs to an existing estimate, supported by documentation.","inDefinedTermSet":"https://connecticutinsuranceappraiser.com/ct-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Umpire","description":"The neutral third member of the appraisal panel who decides items the two appraisers can’t agree on.","inDefinedTermSet":"https://connecticutinsuranceappraiser.com/ct-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Uniform appearance","description":"The goal of repairs that blend with undamaged areas. Related to matching disputes.","inDefinedTermSet":"https://connecticutinsuranceappraiser.com/ct-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Xactimate","description":"Estimating software widely used by insurers and contractors to price repairs by line item.","inDefinedTermSet":"https://connecticutinsuranceappraiser.com/ct-claim-glossary/#definedtermset"}],"@id":"https://connecticutinsuranceappraiser.com/ct-claim-glossary/#definedtermset"}]}</script>
</head>
